const body = $input.first().json.body ?? $input.first().json;
const text = (body.text || '').trim();
if (!text) {
  throw new Error('No text provided in request body');
}
return [{
  json: {
    text,
    user_id: body.user_id || null,
    save_to_supabase: body.save_to_supabase !== false
  }
}];

const raw = $input.first().json.text || $input.first().json.content || '';
const user_id = $('Validate & Extract Input').first().json.user_id;
const save = $('Validate & Extract Input').first().json.save_to_supabase;

// Strip any accidental markdown fences
const clean = raw.replace(/```json|```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(clean);
} catch(e) {
  // Try to extract JSON object from the text
  const match = clean.match(/\{[\s\S]+\}/);
  if (match) {
    parsed = JSON.parse(match[0]);
  } else {
    throw new Error('Claude did not return valid JSON: ' + clean.slice(0, 200));
  }
}

// Build the trip_data object that matches Voyage Genie schema
const participants = (parsed.participants || '')
  .split(',')
  .map(s => s.trim())
  .filter(Boolean);

const tripData = {
  name:          parsed.name        || '',
  tripType:      parsed.tripType    || 'Other',
  destination:   parsed.destination || '',
  startDate:     parsed.startDate   || '',
  endDate:       parsed.endDate     || '',
  groupSize:     parsed.groupSize   ? Number(parsed.groupSize) : (participants.length || ''),
  budget:        parsed.budget      ? Number(parsed.budget)    : '',
  participants,
  people:        participants.map(n => ({ name: n, payer: n })),
  bookingRef:    parsed.bookingRef  || '',
  agent:         parsed.agent       || '',
  notes:         parsed.notes       || '',
  expenses:      [],
  addedManually: true,
  parsedByAI:    true,
  createdAt:     new Date().toISOString()
};

return [{
  json: {
    parsed,
    tripData,
    trip_name: parsed.name || 'My Trip',
    user_id,
    save
  }
}];

